
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"fixed-input-rng-anf-validation-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[2]).unwrap().lines().filter(|x|!x.trim().is_empty()).take(64).map(|x|x.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect()).collect();assert!(!rows.is_empty()&&rows.iter().all(|x|x.len()==6));let cap=args.get(3).map(|x|x.parse().unwrap()).unwrap_or(32);let mut alg=GlobalAnf::new(cap);let mut dummy=seeded(0);let mut initial=Simulator::new(nq as usize,nb as usize,&mut dummy);let mut expected=[vec![0u64;regs[0].len()],vec![0u64;regs[1].len()]];for(lane,row)in rows.iter().enumerate(){for(reg,v)in regs[..4].iter().zip(&row[..4]){initial.set_register(reg,*v,lane);}for reg in 0..2{for i in 0..expected[reg].len(){expected[reg][i]|=(row[4+reg].bit(i)as u64)<<lane;}}}let initialq=initial.qubits.clone();let initialb=initial.bits.clone();drop(initial);let mut q=vec![GlobalAnf::constant(0);nq as usize];let mut b=vec![GlobalAnf::constant(0);nb as usize];let mut input_nodes=Vec::new();for reg in &regs{for wire in reg{let id=alg.dag.variable(false);input_nodes.push((id,*wire));let p=GlobalAnf::constant(id);match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize]=p,QubitOrBit::Bit(id)=>b[id.0 as usize]=p}}}let mut base=GlobalAnf::constant(1);let mut stack=Vec::new();let start=std::time::Instant::now();let mut mr=0usize;
 for(i,o)in ops.iter().enumerate(){use OperationType::*;if matches!(o.kind,Neg|Z|CZ|CCZ|Register|AppendToRegister|DebugPrint){continue;}if o.kind==PopCondition{base=stack.pop().unwrap();continue;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{alg.and(&base,&b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;match o.kind{CCX=>{let v=alg.and(&q[o.q_control1.0 as usize],&q[o.q_control2.0 as usize]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);},CX=>{let v=alg.and(&q[o.q_control1.0 as usize],&c);q[t]=alg.xor(&q[t],&v);},X=>q[t]=alg.xor(&q[t],&c),Swap=>{let a=o.q_control1.0 as usize;let v=alg.xor(&q[t],&q[a]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);q[a]=alg.xor(&q[a],&v);},R|Hmr=>{mr+=1;let random=alg.fresh();let nc=alg.not(&c);q[t]=alg.and(&q[t],&nc);if o.kind==Hmr{let old=alg.and(&b[bt],&nc);let new=alg.and(&random,&c);b[bt]=alg.xor(&old,&new);}},BitStore0=>{let nc=alg.not(&c);b[bt]=alg.and(&b[bt],&nc);},BitStore1=>{let nc=alg.not(&c);let old=alg.and(&b[bt],&nc);b[bt]=alg.xor(&old,&c);},BitInvert=>b[bt]=alg.xor(&b[bt],&c),PushCondition=>{stack.push(base);base=c;},_=>unreachable!()}
 if i%500000==0{eprintln!("GLOBAL_RNG_PROGRESS ops={i} input_nodes={} caps={} fresh_symbols={} seconds={:.1}",alg.dag.nodes.len(),alg.capped,alg.next,start.elapsed().as_secs_f64());}}

 assert!(stack.is_empty());let seconds=start.elapsed().as_secs_f64();let mut output_roots=Vec::new();let mut dependent=0;for reg in&regs[..2]{for wire in reg{let p=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};let rng=p.0.iter().any(|(k,_)|!k.is_empty());dependent+=usize::from(rng);output_roots.push(if rng{None}else{Some(p.0.iter().find(|(k,_)|k.is_empty()).map(|(_,c)|*c).unwrap_or(0))});}}
 // Evaluate only immutable input-only DAG coefficients on a concrete batch.
 // Measurement and capped-unknown symbols never enter this DAG.
 let mut values=vec![0u64;alg.dag.nodes.len()];values[1]=u64::MAX;for(id,wire)in&input_nodes{values[*id as usize]=match wire{QubitOrBit::Qubit(id)=>initialq[id.0 as usize],QubitOrBit::Bit(id)=>initialb[id.0 as usize]};}for(i,node)in alg.dag.nodes.iter().enumerate().skip(2){assert!(!node.random,"RNG-tainted expression entered an input-only coefficient");match node.kind{2=>{},3=>values[i]=values[node.a as usize]^values[node.b as usize],4=>values[i]=values[node.a as usize]&values[node.b as usize],_=>panic!("unexpected coefficient node")}}
 let concrete=|p:&GlobalPoly|{let(mut c,mut d)=(0,0);for(k,v)in&p.0{if k.is_empty(){c^=values[*v as usize]}else{d|=values[*v as usize]}}(c,!d)};let mask=if rows.len()==64{u64::MAX}else{(1u64<<rows.len())-1};let mut wrong=0;let(mut knownbits,mut allbits)=(0usize,0usize);for(reg,expected)in regs[..2].iter().zip(expected.iter()){for(wire,e)in reg.iter().zip(expected){let p=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};let(c,k)=concrete(p);wrong|=(c^e)&k&mask;knownbits+=(k&mask).count_ones()as usize;allbits+=rows.len();}}
 for seed in 0..4{let mut random=seeded(seed);let mut sim=Simulator::new(nq as usize,nb as usize,&mut random);sim.qubits.copy_from_slice(&initialq);sim.bits.copy_from_slice(&initialb);sim.apply_iter(ops.iter());for(i,p)in q.iter().enumerate(){let(c,k)=concrete(p);assert_eq!((sim.qubits[i]^c)&k,0,"global quantum containment wire{i} seed{seed}");}for(i,p)in b.iter().enumerate(){let(c,k)=concrete(p);assert_eq!((sim.bits[i]^c)&k,0,"global classical containment wire{i} seed{seed}");}for lane in 0..rows.len(){if wrong>>lane&1!=0{assert!(sim.get_register(&regs[0],lane)!=rows[lane][4]||sim.get_register(&regs[1],lane)!=rows[lane][5]);}}}
 let report=serde_json::json!({"stream_path":args[1],"term_cap":cap,"input_only_dag_nodes":alg.dag.nodes.len(),"symbolic_input_wires":input_nodes.len(),"all_auxiliary_wires_initial_zero":true,"rng_draws":mr,"fresh_symbols_including_all_inactive_mr_and_opaque_unknowns":alg.next,"capped_expressions":alg.capped,"retained_opaque_nodes":alg.intern.len(),"retained_opaque_hits":alg.hits,"retained_opaque_clears":alg.clears,"output_bits":output_roots.len(),"unresolved_rng_dependent_bits":dependent,"proved_value_rng_independent":dependent==0&&output_roots.len()==512,"output_input_dag_roots":output_roots,"concrete_validation_shots":rows.len(),"concrete_known_output_bits":knownbits,"concrete_total_output_bits":allbits,"concrete_certified_wrong_shots":wrong.count_ones(),"concrete_certified_wrong_mask":format!("{wrong:016x}"),"protected_full_state_containment_seeds":4,"seconds":seconds,"method":"global_exact_rng_polynomials_input_only_dag_coefficients_bounded_opaque_interning","status":"RESEARCH_PROOF_NOT_ENABLED_FOR_SCREENING"});println!("{report}");}
